#!/bin/bash
# Update v2.4.0 release notes in Persian
set -e
cd /home/z/my-project
TOKEN=$(git config --get remote.origin.url | sed -n 's|https://[^:]*:\([^@]*\)@github.com.*|\1|p')
REL_ID=$(curl -s -H "Authorization: Bearer $TOKEN" "https://api.github.com/repos/021hk/modiriat-hesab/releases/tags/v2.4.0" | grep -oP '"id": \K[0-9]+' | head -1)
echo "release id: $REL_ID"

cat > /tmp/release-v240.json <<'EOF'
{
  "name": "حساب‌یار نسخه ۲.۴.۰ — اندروید",
  "body": "## دانلود برنامه اندروید (APK)\n\nفایل **hesab-yar-v2.4.0.apk** را از بخش Assets پایین همین صفحه دانلود و نصب کنید.\n\n## تغییرات این نسخه\n\n### ۱) پیامک ناشناخته هرگز گم نمی‌شود\n- اگر پیامکی از شماره‌های تنظیم‌شده شما رسید ولی برنامه نتوانست مبلغ یا نوعش را تشخیص دهد، **در صف پیامک‌ها ظاهر می‌شود**\n- با دکمه «ثبت تراکنش» می‌توانید مبلغ و نوع (واریز/برداشت) را دستی وارد کنید و ثبتش کنید\n- اگر پیامک مهم نبود (اعلان، موجودی، تبلیغ)، یک ضرب «نادیده» بزنید\n- شماره فرستنده هر پیامک در صف هم نمایش داده می‌شود تا شماره‌های بانک‌تان را بشناسید\n\n### ۲) افزودن چند شماره فرستنده\n- در ویرایش هر حساب بانکی، فیلد شماره فرستنده حالا به‌صورت **چیپ‌های قابل افزودن/حذف** است\n- هر چند شماره که بانک استفاده می‌کند می‌توانید اضافه کنید (بعد از تایپ، Enter بزنید یا دکمه «افزودن» را بزنید)\n- با دکمه × روی هر چیپ می‌توانید شماره را حذف کنید\n\n### امکانات نسخه‌های قبلی (v2.3.0)\n- فقط پیامک‌های شماره‌های تنظیم‌شده خوانده می‌شود\n- تفکیک چند حساب در یک شماره با خط شماره حساب/کارت نقطه‌دار (مثل `777.888.13972872.1`)\n- تشخیص واریز/برداشت/خرید با علامت یا کلمات\n- ریال/تومان، حالت شب/روز، بدون داده الکی\n\n## روش نصب\n\n1. فایل APK را دانلود و نصب کنید (روی نسخه قبلی هم نصب می‌شود؛ داده‌ها می‌ماند)\n2. اولین باز شدن، دسترسی پیامک را تأیید کنید\n3. در تب «بانک‌ها» حساب را ویرایش کنید و شماره(های) فرستنده پیامک را اضافه کنید\n"
}
EOF

curl -s -X PATCH -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" \
  -d @/tmp/release-v240.json "https://api.github.com/repos/021hk/modiriat-hesab/releases/$REL_ID" | grep -oP '"name": "\Kحساب[^"]*' | head -1
echo DONE
